-- GENERATED by `npm run db:sql` from src/data + supabase/schema.sql. Do not edit by hand.
-- DESTRUCTIVE: drops and recreates the 9 portfolio tables in the public schema, then seeds them.
-- Storage buckets and Auth users are not touched. Paste into Supabase Dashboard -> SQL Editor -> Run.

BEGIN;

DROP TABLE IF EXISTS public.profiles, public.projects, public.work_history, public.education, public.languages, public.frontend, public.backend, public.workflow_ai, public.coding_tools CASCADE;

-- Full portfolio schema for Supabase (consolidates supabase/migrations/).
-- Applied by scripts/seed.ts (npm run db:reset) after dropping the tables.
--
-- Access model: the browser uses the anon key, so RLS is the only guard.
--   * anon + authenticated: SELECT on every table (hidden rows are filtered in the UI).
--   * authenticated only (the admin signed in via Supabase Auth): INSERT / UPDATE / DELETE.
-- Storage bucket "portfolio-images" and its policies live in the storage schema and are untouched.

CREATE TABLE IF NOT EXISTS profiles (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  full_name TEXT NOT NULL,
  full_name_vi TEXT,
  title TEXT,
  title_vi TEXT,
  bio TEXT,
  bio_vi TEXT,
  avatar_url TEXT,
  avatar_x REAL DEFAULT 50,
  avatar_y REAL DEFAULT 50,
  avatar_scale REAL DEFAULT 1,
  cv_url TEXT,
  email TEXT,
  location TEXT,
  location_vi TEXT,
  work_format TEXT,
  work_format_vi TEXT,
  gender TEXT DEFAULT 'he/him',
  github_url TEXT,
  linkedin_url TEXT,
  facebook_url TEXT,
  instagram_url TEXT,
  stats_languages INTEGER,
  stats_tools INTEGER,
  stats_experience INTEGER,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS projects (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  title TEXT NOT NULL,
  title_vi TEXT,
  role TEXT,
  role_vi TEXT,
  description TEXT,
  description_vi TEXT,
  features TEXT[] NOT NULL DEFAULT '{}',
  features_vi TEXT[] NOT NULL DEFAULT '{}',
  images JSONB NOT NULL DEFAULT '[]'::jsonb,
  logo_url TEXT,
  tech_stack TEXT[] NOT NULL DEFAULT '{}',
  team_size INTEGER DEFAULT 1,
  demo_url TEXT,
  github_url TEXT,
  start_date DATE,
  end_date DATE,
  show_dates BOOLEAN NOT NULL DEFAULT TRUE,
  is_hidden BOOLEAN NOT NULL DEFAULT FALSE,
  is_featured BOOLEAN NOT NULL DEFAULT FALSE,
  display_order INTEGER NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS work_history (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  company TEXT NOT NULL,
  company_vi TEXT,
  role TEXT,
  role_vi TEXT,
  work_type TEXT,
  work_type_vi TEXT,
  location TEXT,
  location_vi TEXT,
  logo_url TEXT,
  start_date DATE,
  end_date DATE,
  description TEXT,
  description_vi TEXT,
  tech_stack TEXT[] NOT NULL DEFAULT '{}',
  is_hidden BOOLEAN NOT NULL DEFAULT FALSE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS education (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  school TEXT NOT NULL,
  school_vi TEXT,
  degree TEXT,
  degree_vi TEXT,
  major TEXT,
  major_vi TEXT,
  start_date DATE,
  end_date DATE,
  logo_url TEXT,
  description TEXT,
  description_vi TEXT,
  tech_stack TEXT[] NOT NULL DEFAULT '{}',
  is_hidden BOOLEAN NOT NULL DEFAULT FALSE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS languages (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name TEXT NOT NULL,
  logo_url TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS frontend (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name TEXT NOT NULL,
  logo_url TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS backend (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name TEXT NOT NULL,
  logo_url TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS workflow_ai (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name TEXT NOT NULL,
  logo_url TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS coding_tools (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name TEXT NOT NULL,
  logo_url TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS projects_display_order_idx ON projects (display_order);

-- Row Level Security: public read, admin-only write.
ALTER TABLE profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE projects ENABLE ROW LEVEL SECURITY;
ALTER TABLE work_history ENABLE ROW LEVEL SECURITY;
ALTER TABLE education ENABLE ROW LEVEL SECURITY;
ALTER TABLE languages ENABLE ROW LEVEL SECURITY;
ALTER TABLE frontend ENABLE ROW LEVEL SECURITY;
ALTER TABLE backend ENABLE ROW LEVEL SECURITY;
ALTER TABLE workflow_ai ENABLE ROW LEVEL SECURITY;
ALTER TABLE coding_tools ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Public read" ON profiles FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "Admin write" ON profiles FOR ALL TO authenticated USING (true) WITH CHECK (true);
CREATE POLICY "Public read" ON projects FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "Admin write" ON projects FOR ALL TO authenticated USING (true) WITH CHECK (true);
CREATE POLICY "Public read" ON work_history FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "Admin write" ON work_history FOR ALL TO authenticated USING (true) WITH CHECK (true);
CREATE POLICY "Public read" ON education FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "Admin write" ON education FOR ALL TO authenticated USING (true) WITH CHECK (true);
CREATE POLICY "Public read" ON languages FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "Admin write" ON languages FOR ALL TO authenticated USING (true) WITH CHECK (true);
CREATE POLICY "Public read" ON frontend FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "Admin write" ON frontend FOR ALL TO authenticated USING (true) WITH CHECK (true);
CREATE POLICY "Public read" ON backend FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "Admin write" ON backend FOR ALL TO authenticated USING (true) WITH CHECK (true);
CREATE POLICY "Public read" ON workflow_ai FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "Admin write" ON workflow_ai FOR ALL TO authenticated USING (true) WITH CHECK (true);
CREATE POLICY "Public read" ON coding_tools FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "Admin write" ON coding_tools FOR ALL TO authenticated USING (true) WITH CHECK (true);

-- Explicit table privileges (newer Supabase projects may not grant these by default).
-- RLS above still decides which rows each role can touch.
GRANT USAGE ON SCHEMA public TO anon, authenticated, service_role;
GRANT SELECT ON profiles, projects, work_history, education, languages, frontend, backend, workflow_ai, coding_tools TO anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON profiles, projects, work_history, education, languages, frontend, backend, workflow_ai, coding_tools TO authenticated;
GRANT ALL ON profiles, projects, work_history, education, languages, frontend, backend, workflow_ai, coding_tools TO service_role;

-- Ask the Supabase Data API (PostgREST) to pick up the new tables immediately.
NOTIFY pgrst, 'reload schema';

INSERT INTO public.profiles ("full_name", "full_name_vi", "title", "title_vi", "bio", "bio_vi", "avatar_url", "avatar_x", "avatar_y", "avatar_scale", "cv_url", "email", "location", "location_vi", "work_format", "work_format_vi", "gender", "github_url", "linkedin_url", "facebook_url", "instagram_url", "stats_languages", "stats_tools", "stats_experience") VALUES ('Le Duc Trong', 'Lê Đức Trọng', 'Software Engineering', 'Kỹ thuật Phần mềm', 'Driven by a long-standing interest in programming, I am a Full-stack Developer focusing on ASP.NET and Next.js. Having experienced roles as both a team contributor and leader, I value the importance of adaptability and constant self-improvement. I am eager to apply my current knowledge while learning from experienced mentors in a professional setting.', 'Xuất phát từ niềm đam mê lập trình lâu năm, tôi là một lập trình viên Full-stack chuyên về ASP.NET và Next.js. Từng đảm nhiệm cả vai trò thành viên nhóm và người lãnh đạo, tôi đánh giá cao tầm quan trọng của khả năng thích ứng và tự hoàn thiện bản thân không ngừng. Tôi mong muốn được áp dụng kiến thức hiện có đồng thời học hỏi từ những người hướng dẫn giàu kinh nghiệm trong môi trường chuyên nghiệp.', '/portfolio-images/profile/avatar_0.7536902475208322.png', 48, 19, 1.9, '/portfolio-images/profile/cv_0.5386134662060291.pdf', 'trongle1161@gmail.com', 'Vietnam', 'Việt Nam', 'Full-time / Freelancer, Full-time, Onsite', 'Toàn thời gian / Freelancer, Onsite', 'he/him', 'https://github.com/trongleduc', 'https://www.linkedin.com/in/trong-le-duc/', 'https://www.facebook.com/trong.le.26298', 'https://www.instagram.com/accounts/edit/?hl=en', 3, 9, 1);
INSERT INTO public.projects ("id", "title", "title_vi", "role", "role_vi", "description", "description_vi", "start_date", "end_date", "show_dates", "team_size", "demo_url", "github_url", "logo_url", "tech_stack", "features", "features_vi", "images", "is_hidden", "display_order") VALUES ('664ac052-4e91-488f-b407-20823714fe6b', 'TikTok Statistics Tracker', 'Trình theo dõi thống kê TikTok', 'Full-stack Developer', 'Lập trình viên full-stack', '<ul><li><p>Description: Tracked performance statistics of 30+ TikTok channels for a content creation team. Integrated a script approval feature to easily submit, review, and approve video scripts before production.</p></li><li><p>Key Metrics: Supported 30+ concurrent users, completed 30+ core functions, and built 25+ interactive screens.</p></li></ul>', '<ul><li><p>Mô tả: Thống kê hiệu suất được theo dõi của hơn 30 kênh TikTok cho nhóm sáng tạo nội dung. Tích hợp tính năng phê duyệt kịch bản để dễ dàng gửi, xem xét và phê duyệt kịch bản video trước khi sản xuất.</p></li><li><p>Số liệu chính: Đã hỗ trợ hơn 30 người dùng đồng thời, hoàn thành hơn 30 chức năng cốt lõi và xây dựng hơn 25 màn hình tương tác.</p></li></ul>', '2026-01-01', '2026-03-15', TRUE, 1, '', '', '/portfolio-images/project-logos/0.20234692610993033.png', ARRAY['Next.js', 'React', 'TypeScript', 'Firebase', 'TikTok API', 'NoSQL', 'Deployment']::text[], ARRAY['Multi-Team Channel Management: Efficiently organize and track multiple TikTok channels categorized by specific content teams.', 'Real-time Analytics Dashboard: Integrated TikTok APIs to monitor and visualize key performance metrics (views, followers, engagement) in real-time.', 'Automated Reporting System: Generate comprehensive performance reports with flexible options for monthly summaries or custom date ranges.', 'Script Workflow Automation: A dedicated module for content creation that allows members to submit scripts and managers to review, comment, and approve/reject.', 'AI-Accelerated Development: Leveraged AI tools to optimize code architecture and speed up the full-stack development process as a solo developer.', 'Scalable Cloud Infrastructure: Built with Next.js and Firebase to ensure high performance, secure authentication, and seamless data synchronization.']::text[], ARRAY['Quản lý kênh theo nhóm: Tổ chức và theo dõi nhiều kênh TikTok khác nhau, phân loại theo từng nhóm nội dung riêng biệt.', 'Bảng điều khiển chỉ số thời gian thực: Tích hợp TikTok API để theo dõi trực quan các thông số quan trọng như lượt xem, người theo dõi và tương tác.', 'Hệ thống báo cáo tự động: Hỗ trợ xuất báo cáo hiệu suất chi tiết theo tháng hoặc tùy chỉnh linh hoạt theo khoảng thời gian yêu cầu.', 'Quy trình duyệt kịch bản: Cung cấp không gian làm việc chuyên nghiệp, cho phép thành viên gửi kịch bản và quản lý phê duyệt hoặc phản hồi trực tiếp trên hệ thống.', 'Phát triển tối ưu với AI: Ứng dụng các công cụ trí tuệ nhân tạo để tăng tốc độ viết code và giải quyết vấn đề, giúp hoàn thành dự án quy mô full-stack một mình.', 'Hạ tầng đám mây hiện đại: Sử dụng Next.js kết hợp với Firebase giúp hệ thống vận hành ổn định, bảo mật và đồng bộ dữ liệu tức thời.']::text[], '[{"url":"/portfolio-images/projects/0.9251321757765737.png","x":73.5,"y":46.3,"scale":1},{"url":"/portfolio-images/projects/0.5252616474215187.png","x":50,"y":50,"scale":1},{"url":"/portfolio-images/projects/0.6439120047190507.png","x":50,"y":50,"scale":1},{"url":"/portfolio-images/projects/0.7543076686460025.png","x":50,"y":50,"scale":1}]'::jsonb, FALSE, 0);
INSERT INTO public.projects ("id", "title", "title_vi", "role", "role_vi", "description", "description_vi", "start_date", "end_date", "show_dates", "team_size", "demo_url", "github_url", "logo_url", "tech_stack", "features", "features_vi", "images", "is_hidden", "display_order") VALUES ('02e6cd79-a5a3-4f49-966c-c7cc238709f9', 'Perhue mobile application', 'Ứng dụng di động Perhue', 'Mobile Developer', 'Lập trình viên mobile', '<ul><li><p>Description: Personal color analysis ecosystem featuring AI-powered detection, virtual try-on, and expert consulting platform.</p></li><li><p>Key Metrics: 40+ mobile screens within deadline.</p></li></ul>', '<ul><li><p>Mô tả: Hệ sinh thái phân tích màu sắc cá nhân có tính năng phát hiện được hỗ trợ bởi AI, thử nghiệm ảo và nền tảng tư vấn chuyên gia.</p></li><li><p>Số liệu chính: Hơn 40 màn hình di động trong thời hạn.</p></li></ul>', '2025-09-08', '2025-12-28', TRUE, 1, '', 'https://github.com/trongleduc/PerHue-mobile', '/portfolio-images/project-logos/0.4052806633210424.png', ARRAY['React Native', 'Expo', 'TypeScript', 'Android']::text[], ARRAY['Real-time Camera Filters: Allows users to manually test colors using live camera overlays to identify their personal color palette.', 'Seasonal Capsule Palettes: Provides a curated library of seasonal color sets for styling, outfit coordination, and reference.', 'AI & Expert Analysis: Dual-layer system offering instant AI color detection and personalized feedback from certified experts.', 'Expert Management Portal: Features a professional registration flow and a dedicated interface for experts to send results directly to users.', 'Personalized Storage: Enables users to save their analysis history and personal palettes for easy access during shopping or styling.']::text[], ARRAY['Bộ lọc Camera thời gian thực: Cho phép người dùng thử các tông màu trực tiếp qua camera để xác định màu sắc cá nhân một cách thủ công.', 'Bảng màu theo mùa (Capsule Palette): Cung cấp các thư viện màu sắc được phân loại theo mùa, hỗ trợ người dùng trong việc phối đồ và tham khảo.', 'Phân tích kép AI & Chuyên gia: Cung cấp hai lựa chọn: nhận kết quả nhanh từ AI hoặc nhận tư vấn chuyên sâu từ các chuyên gia thực tế.', 'Cổng thông tin chuyên gia: Hệ thống đăng ký và phê duyệt chuyên gia, cho phép họ tương tác và gửi kết quả phân tích trực tiếp cho khách hàng ngay trên app.', 'Lưu trữ kết quả cá nhân: Hỗ trợ lưu lại lịch sử phân tích và các bảng màu phù hợp để người dùng dễ dàng tra cứu khi cần thiết.']::text[], '[{"url":"/portfolio-images/projects/0.934183089084482.png","x":50,"y":50,"scale":1},{"url":"/portfolio-images/projects/0.07586289686845926.png","x":50,"y":50,"scale":1},{"url":"/portfolio-images/projects/0.6560366912244874.png","x":50,"y":50,"scale":1},{"url":"/portfolio-images/projects/0.23666550594497726.png","x":50,"y":50,"scale":1},{"url":"/portfolio-images/projects/0.06764394623095682.png","x":50,"y":50,"scale":1},{"url":"/portfolio-images/projects/0.12931648903762039.png","x":50,"y":50,"scale":1}]'::jsonb, FALSE, 1);
INSERT INTO public.projects ("id", "title", "title_vi", "role", "role_vi", "description", "description_vi", "start_date", "end_date", "show_dates", "team_size", "demo_url", "github_url", "logo_url", "tech_stack", "is_hidden", "display_order") VALUES ('2e824389-9863-481b-a01d-cd3883add451', 'Perhue API', 'Perhue API', 'Backend Developer / Team Leader', 'Lập trình viên backend / Trưởng nhóm', '<ul><li><p>Description: Personal color analysis ecosystem featuring AI-powered detection, virtual try-on, and expert consulting platform.</p></li><li><p>Key Actions: Led a 4-member team, managed project documentation, designed ASP.NET RESTful APIs with Clean Architecture, integrated Gemini AI API.</p></li><li><p>Key Metrics: Delivered 35+ functions within deadline.</p></li></ul>', '<ul><li><p>Mô tả: Hệ sinh thái phân tích màu sắc cá nhân có tính năng phát hiện được hỗ trợ bởi AI, thử nghiệm ảo và nền tảng tư vấn chuyên gia.</p></li><li><p>Hành động chính: Dẫn dắt nhóm 4 thành viên, quản lý tài liệu dự án, thiết kế API ASP.NET RESTful với Clean Architecture, tích hợp Gemini AI API.</p></li><li><p>Các số liệu chính: Đã cung cấp hơn 35 chức năng trong thời hạn.</p></li></ul>', '2025-09-01', '2025-12-30', TRUE, 4, '', 'https://github.com/trongleduc/PerHue-api', '/portfolio-images/project-logos/0.7145265869680076.png', ARRAY['ASP.NET Core Web API', 'Azure SQL Database', 'JWT', 'Gemini AI API', 'Clean Architecture']::text[], FALSE, 2);
INSERT INTO public.projects ("id", "title", "title_vi", "role", "role_vi", "description", "description_vi", "start_date", "end_date", "show_dates", "team_size", "demo_url", "github_url", "logo_url", "tech_stack", "features", "features_vi", "images", "is_hidden", "display_order") VALUES ('684ff66d-13ff-4f7a-9fee-abfdde4000be', 'FSTEP', 'FSTEP', 'Full-stack Developer / Member', 'Lập trình viên full-stack / Thành viên', '<ul><li><p>Description: A mini e-commerce and barter platform tailored specifically for the FPT University student community to trade and exchange used items.</p></li><li><p>Key Actions: Developed both frontend and backend components, designed the system architecture using ASP.NET Core MVC, implemented core business logic for product listings, and optimized SQL Server database queries.</p></li><li><p>Key Metrics: Successfully completed 15+ functions and built 20+ responsive web screens within the project deadline.</p></li></ul>', '<ul><li><p>Mô tả: Nền tảng thương mại điện tử và trao đổi hàng mini được thiết kế riêng cho cộng đồng sinh viên Đại học FPT để trao đổi, mua bán các mặt hàng đã qua sử dụng.</p></li><li><p>Hành động chính: Phát triển cả thành phần giao diện người dùng và phụ trợ, thiết kế kiến trúc hệ thống bằng ASP.NET Core MVC, triển khai logic nghiệp vụ cốt lõi cho danh sách sản phẩm và tối ưu hóa truy vấn SQL Server.</p></li><li><p>Các số liệu chính: Đã hoàn thành thành công hơn 15 chức năng và xây dựng hơn 20 màn hình web phản hồi trong thời hạn dự án.</p></li></ul>', '2024-05-06', '2024-07-11', TRUE, 4, '', 'https://github.com/trongleduc/FSTEP', '/portfolio-images/project-logos/0.7446966395170866.png', ARRAY['ASP.NET Core MVC', 'HTML/CSS', 'jQuery', 'Ajax', 'Bootstrap', 'SQL Server']::text[], ARRAY['Student Marketplace: A specialized platform for posting, managing, and exchanging used items.', 'Real-time Communication: Integrated online chat for direct negotiation between students.', 'Trust & Reputation System: Implemented "Credibility Points" to ensure a safe and transparent exchange environment.', 'Comprehensive Order Tracking: Full history logs and real-time status updates for every transaction.']::text[], ARRAY['Sàn trao đổi sinh viên: Nền tảng chuyên biệt để đăng tin, quản lý và trao đổi vật dụng cũ.', 'Chat trực tuyến: Tích hợp tính năng nhắn tin thời gian thực giúp người mua và người bán dễ dàng kết nối.', 'Hệ thống điểm uy tín: Cơ chế đánh giá độ tin cậy để đảm bảo môi trường giao dịch an toàn và minh bạch.', 'Quản lý lịch sử & Trạng thái: Theo dõi chi tiết mọi giao dịch và trạng thái hàng hóa theo thời gian thực.']::text[], '[{"url":"/portfolio-images/projects/0.3267120763401673.png","x":50,"y":50,"scale":1},{"url":"/portfolio-images/projects/0.8407684980614553.png","x":50,"y":50,"scale":1},{"url":"/portfolio-images/projects/0.6253341895145518.png","x":50,"y":50,"scale":1},{"url":"/portfolio-images/projects/0.9874128159396024.png","x":50,"y":50,"scale":1},{"url":"/portfolio-images/projects/0.17126181007017227.png","x":50,"y":50,"scale":1}]'::jsonb, FALSE, 3);
INSERT INTO public.projects ("id", "title", "title_vi", "role", "role_vi", "description", "description_vi", "start_date", "end_date", "show_dates", "team_size", "demo_url", "github_url", "logo_url", "tech_stack", "features", "features_vi", "is_hidden", "display_order") VALUES ('7c08011a-6b82-43e1-b8e8-9765ba880870', 'Portfolio TrongLe', 'Portfolio TrongLe', 'Full-stack Developer', 'Lập trình viên Full-stack', '<ul><li><p>Description: A bilingual (EN/VI) one-page portfolio with a built-in inline CMS. After unlocking admin mode, every section (profile, journey timeline, projects and tech stack) is edited in place on the live page and saved straight to Supabase.</p></li><li><p>Key Metrics: 6 interactive sections, 9 database tables guarded by Row Level Security, light/dark mode with two colour themes, and layouts tuned for both phones and laptops.</p></li></ul>', '<ul><li><p>Mô tả: Trang portfolio một trang song ngữ (Anh/Việt) có sẵn CMS chỉnh sửa trực tiếp. Sau khi mở khóa chế độ admin, mọi phần (hồ sơ, timeline hành trình, dự án và tech stack) đều được sửa ngay trên trang đang chạy và lưu thẳng vào Supabase.</p></li><li><p>Số liệu chính: 6 phần tương tác, 9 bảng dữ liệu được bảo vệ bằng Row Level Security, chế độ sáng/tối cùng hai bộ màu, bố cục tối ưu cho cả điện thoại và laptop.</p></li></ul>', '2026-03-01', '2026-08-07', TRUE, 1, '', 'https://github.com/trongleduc/portfolio', '/portfolio-images/project-logos/0.6723890737872115.png', ARRAY['Next.js', 'React', 'TypeScript', 'Tailwind CSS', 'Supabase', 'PostgreSQL', 'GSAP', 'Vercel']::text[], ARRAY['Inline CMS: Edit the profile, timeline, projects and tech stack directly on the live page, with image uploads to Supabase Storage.', 'Bilingual content: Every text field has an English and a Vietnamese version, switched instantly from the navigation bar.', 'Video-editor timeline: Work and study entries packed onto layers, with a scrubbable playhead, playback, zoom and an inspector panel.', 'Interactive tech-stack desk: Each object on the desk opens a technology category and the scene scales to fit any screen.', 'Raised design system: Shared extruded blocks, recessed wells and accent states across light/dark mode and two colour themes.', 'Supabase backend: Postgres schema with Row Level Security, server-rendered first load and client-side CRUD.']::text[], ARRAY['CMS chỉnh sửa trực tiếp: Sửa hồ sơ, timeline, dự án và tech stack ngay trên trang, tải ảnh lên Supabase Storage.', 'Nội dung song ngữ: Mỗi trường văn bản có bản tiếng Anh và tiếng Việt, chuyển đổi tức thì từ thanh điều hướng.', 'Timeline kiểu dựng video: Công việc và học tập xếp theo từng layer, có playhead kéo được, phát tự động, zoom và bảng chi tiết.', 'Bàn làm việc tech stack tương tác: Mỗi vật trên bàn mở một nhóm công nghệ, toàn cảnh tự co giãn vừa mọi màn hình.', 'Hệ thống thiết kế dạng khối nổi: Khối nổi, ô lõm và trạng thái màu nhấn thống nhất ở chế độ sáng/tối và hai bộ màu.', 'Backend Supabase: Lược đồ Postgres có Row Level Security, dữ liệu render sẵn từ server và CRUD phía client.']::text[], FALSE, 4);
INSERT INTO public.work_history ("id", "company", "company_vi", "role", "role_vi", "work_type", "work_type_vi", "location", "location_vi", "logo_url", "start_date", "end_date", "description", "description_vi", "tech_stack", "is_hidden") VALUES ('28e78aeb-3312-402a-9e1e-21ef6cc79499', 'FPT University', 'Đại Học FPT', 'Freelancer', 'Freelancer', 'Service Contract', 'Hợp đồng dịch vụ', 'Ho Chi Minh City', 'Thành phố Hồ Chí Minh', '/portfolio-images/logos/0.0375247727454705.png', '2026-01-01', '2026-02-15', '<ul><li><p>Developed a TikTok Statistics Tracker web application under a service contract for FPT University Campus Ho Chi Minh</p></li><li><p>Handled end-to-end development to deliver a high-performance analytics tool tailored for content creation teams</p></li></ul>', '<ul><li><p>Phát triển ứng dụng web theo dõi số liệu thống kê TikTok theo hợp đồng dịch vụ cho Đại học FPT cơ sở TP.HCM.</p></li><li><p>Đảm nhiệm toàn bộ quy trình phát triển để cung cấp công cụ phân tích hiệu suất cao, được thiết kế riêng cho các đội ngũ sáng tạo nội dung.</p></li></ul>', ARRAY['Next.js', 'React', 'TypeScript', 'Firebase', 'TikTok API', 'NoSQL', 'Deployment']::text[], FALSE);
INSERT INTO public.work_history ("id", "company", "company_vi", "role", "role_vi", "work_type", "work_type_vi", "location", "location_vi", "logo_url", "start_date", "end_date", "description", "description_vi", "tech_stack", "is_hidden") VALUES ('73e4a887-8287-4c2c-826c-83f9c10d25ad', 'FPT Software', 'FPT Software', 'Intern', 'Intern', 'Full-time', 'Toàn thời gian', 'Ho Chi Minh City', 'Thành phố Hồ Chí Minh', '/portfolio-images/logos/0.7147347145511291.png', '2024-10-02', '2024-12-02', '<ul><li><p>Developed and maintained internal enterprise tools using C#, improving system performance for internal operations.</p></li><li><p>Collaborated with the team to troubleshoot system issues, optimize code quality, and implement new features.</p></li></ul><p></p>', '<ul><li><p>Phát triển và duy trì các công cụ nội bộ doanh nghiệp bằng C#, giúp cải thiện hiệu suất hệ thống cho các hoạt động nội bộ.</p></li><li><p>Phối hợp với nhóm để khắc phục sự cố hệ thống, tối ưu hóa chất lượng mã nguồn và triển khai các tính năng mới.</p></li></ul><p></p>', ARRAY['C#', 'Python', 'Microsoft Power Automate', 'Teamwork']::text[], FALSE);
INSERT INTO public.education ("id", "school", "school_vi", "degree", "degree_vi", "major", "major_vi", "start_date", "end_date", "logo_url", "description", "description_vi", "tech_stack", "is_hidden") VALUES ('702f51db-3b84-474a-9522-b940789bc708', 'FPT University', 'Đại học FPT', 'Bachelor''s degree', 'Cử nhân', 'Software Engineering', 'Kỹ thuật phần mềm', '2023-01-01', '2026-03-01', '', '<ul><li><p>Studied at FPT University campus Ho Chi Minh City</p></li><li><p>Bachelor''s degree in Information Technology, majoring in Software Engineering</p></li><li><p>Academic studies and active participation in university student activities</p></li></ul>', '<ul><li><p>Học tại trường Đại học FPT phân hiệu TP.HCM</p></li><li><p>Bằng cử nhân Công nghệ Thông tin, chuyên ngành Kỹ thuật Phần mềm</p></li><li><p>Học tập và tích cực tham gia vào các hoạt động sinh viên tại trường</p></li></ul>', ARRAY['C#', '.NET', 'ASP.NET', 'C', 'Java', 'SQL', 'Web Design', 'SQL Server']::text[], FALSE);
